import{z as A,x as d,o as r,c as p,q as i,j as n,D as e,d as l,s as E,S as s,b as t}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"定位与指代","description":"","frontmatter":{"title":"定位与指代","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/grounding-referring.md","filePath":"llm/grounding-referring.md","lastUpdated":1791063341000}'),B={name:"llm/grounding-referring.md"};function m(h,a,C,c,f,u){const o=d("Mermaid");return r(),p("div",null,[a[2]||(a[2]=i('<h1 id="定位与指代" tabindex="-1">定位与指代 <a class="header-anchor" href="#定位与指代" aria-label="Permalink to &quot;定位与指代&quot;">​</a></h1><div class="epigraph"><p>「左边那只猫」不是分类标签。短语必须落到像素坐标，语言侧的共现才不能顶替格子上的证据。</p><footer>—— Peng 等 Kosmos-2；Chen 等 Shikra；指代基准 RefCOCO / RefCOCO+ / RefCOCOg</footer></div><p><a href="/llm/vlm-hallucination">上一课</a>用 POPE 抓住乱认物体。缺口是绑定：名词、代词、关系短语要对准图上的区域，而不是只答「有」。后课 GUI 默认同一套指代，只是画布换成屏幕控件。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/clip">CLIP</a> 对齐的是全局图与整句，不给词–区域。开放 VQA 可以靠主题蒙对。指代理解（REC）要求：给定指代表达，输出框；指代生成（REG）相反。RefCOCO 家族用游戏收集的短语，含位置（左边）、外观、关系；RefCOCO+ 弱化纯位置词，更考外观。</p><p><span class="marginnote">术语翻译：REC（指代理解）是「听懂你说的哪个东西，画出框」；REG（指代生成）反过来，是「看着框，说出区分它的说法」。两个任务用同一张图、同一套短语，只是输入输出对调。</span></p><p>VLM 要把框写成可生成的 token：量化坐标、特殊位置词、或与文本交错的 <code>&lt;x&gt;&lt;y&gt;</code>。没有这项监督，<a href="/llm/llava-projector">LLaVA 投影器</a> 的 patch 序列只是「可能被注意到的键」，定位是涌现、不保证框准。</p><p><span class="marginnote">坐标协议是产品：归一到 \\([0,1000]\\)、原图像素、还是 patch 下标，训练与推理必须同一套。分辨率一变，未归一的绝对像素会漂。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Kosmos-2 把位置写进语言序列，用图文与接地数据联合训。Shikra 在对话里直接输出坐标，强调 referential dialogue。实现上：<a href="/llm/vit-as-encoder">ViT</a> 必须保留空间 patch，不能只投 CLS；2D 位置（<a href="/llm/2d-rope">2D RoPE</a>）让「左/上」可学。评测用 Acc@IoU，并分短短语与长关系句。不要用 POPE 替代 REC。</p><p><span class="marginnote">常见误区：以为两个框「沾到边」就算指对了。评测用的 Acc@IoU 先算预测框与真值框的重叠比例 IoU（完全不重叠是 0，完全重合是 1），超过阈值（常见 0.5）才记命中——「碰了个边」的 0.1 是不及格的。</span></p>',11)),(r(),n(s,null,{default:e(()=>[E(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PH%5B%22%E6%8C%87%E4%BB%A3%E8%A1%A8%E8%BE%BE%22%5D%20--%3E%20LLM%5B%22%E5%9B%A0%E6%9E%9C%20LLM%22%5D%0A%20%20PATCH%5B%22%E7%A9%BA%E9%97%B4%20patch%22%5D%20--%3E%20LLM%0A%20%20LLM%20--%3E%20BOX%5B%22%E6%A1%86%E6%88%96%E7%82%B9%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[l("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"指代成功时，注意力应把短语里的约束（颜色、方位、第几个）打到对应 patch 的键上，再把坐标解码出来。这给物体名词一条必须经过视觉格子的路径，比纯「是否存在」更难用语言先验蒙混——编造的物体没有稳定的框可抄。",-1)),(r(),n(s,null,{default:e(()=>[E(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E7%9F%AD%E8%AF%AD%EF%BC%9A%E5%B7%A6%E8%BE%B9%E9%82%A3%E5%8F%AA%E6%A9%99%E8%89%B2%E7%9A%84%E7%8C%AB%22%5D%20--%3E%20C1%5B%22%E7%BA%A6%E6%9D%9F%201%EF%BC%9A%E7%B1%BB%E5%88%AB%20%3D%20%E7%8C%AB%22%5D%0A%20%20P%20--%3E%20C2%5B%22%E7%BA%A6%E6%9D%9F%202%EF%BC%9A%E6%96%B9%E4%BD%8D%20%3D%20%E5%B7%A6%22%5D%0A%20%20P%20--%3E%20C3%5B%22%E7%BA%A6%E6%9D%9F%203%EF%BC%9A%E5%A4%96%E8%A7%82%20%3D%20%E6%A9%99%E8%89%B2%22%5D%0A%20%20C1%20--%3E%20A%5B%22%E6%B3%A8%E6%84%8F%E5%8A%9B%E9%80%90%E6%A0%BC%E6%A0%B8%E5%AF%B9%20patch%22%5D%0A%20%20C2%20--%3E%20A%0A%20%20C3%20--%3E%20A%0A%20%20A%20--%3E%20B%5B%22%E8%A7%A3%E7%A0%81%E5%87%BA%E5%94%AF%E4%B8%80%E7%9A%84%E6%A1%86%20%2F%20%E7%82%B9%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<p><span class="marginnote">直觉类比：如果 ViT 只输出一个「整图摘要」向量，就像看照片只记住「里面有一只猫」；要指出「左边那只」，必须保留一格一格的空间布局，让每个格子带着自己的位置编号，短语里的约束才能逐格核对。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>自然图框不是点击 UI。下一课把坐标系换成屏幕像素与控件，评测也从 IoU 换成点击命中。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>定位把短语钉到框/点，堵住只靠共现的物体幻觉。</li><li>必须保留空间 token 与坐标协议。</li><li>RefCOCO 家族测的是指代，不是开放描述。</li><li>出处：Kosmos-2；Shikra；RefCOCO 系列。</li></ul>',5))])}const _=A(B,[["render",m]]);export{g as __pageData,_ as default};
